import js from '@eslint/js'
import tseslint from 'typescript-eslint'
import nextCoreWebVitals from 'eslint-config-next/core-web-vitals'
import nextTypescript from 'eslint-config-next/typescript'

export default tseslint.config(
  {
    ignores: [
      'legacy/**',
      '.next/**',
      'node_modules/**',
      'dist/**',
      'coverage/**',
      'playwright-report/**',
      'test-results/**',
      'src/types/database.ts', // generated by `npm run db:types`
      'next-env.d.ts',
      'supabase/.temp/**',
      'supabase/.branches/**',
      'supabase/functions/**', // Deno runtime, linted separately
    ],
  },

  js.configs.recommended,
  ...tseslint.configs.recommendedTypeChecked,
  ...nextCoreWebVitals,
  ...nextTypescript,

  {
    languageOptions: {
      parserOptions: {
        projectService: {
          // Only the .mjs configs need this — tsconfig's `**/*.ts` glob already
          // covers next.config.ts, vitest.config.ts, and playwright.config.ts.
          allowDefaultProject: ['*.config.mjs'],
        },
        tsconfigRootDir: import.meta.dirname,
      },
    },
    rules: {
      // The prototype carried 107 lint errors, the bulk of them `any`.
      // Non-negotiable in the rebuild.
      '@typescript-eslint/no-explicit-any': 'error',
      '@typescript-eslint/no-unsafe-assignment': 'error',
      '@typescript-eslint/no-unsafe-member-access': 'error',
      '@typescript-eslint/no-unsafe-call': 'error',
      '@typescript-eslint/no-unsafe-return': 'error',
      '@typescript-eslint/no-unsafe-argument': 'error',

      // Unused vars are errors, but an underscore prefix is an explicit opt-out.
      '@typescript-eslint/no-unused-vars': [
        'error',
        {
          argsIgnorePattern: '^_',
          varsIgnorePattern: '^_',
          caughtErrorsIgnorePattern: '^_',
        },
      ],

      // Floating promises were how the prototype lost errors silently.
      '@typescript-eslint/no-floating-promises': 'error',
      '@typescript-eslint/no-misused-promises': [
        'error',
        { checksVoidReturn: { attributes: false } },
      ],
      '@typescript-eslint/await-thenable': 'error',
      '@typescript-eslint/require-await': 'error',

      // `import type` must be explicit — required by verbatimModuleSyntax.
      '@typescript-eslint/consistent-type-imports': [
        'error',
        { prefer: 'type-imports', fixStyle: 'inline-type-imports' },
      ],

      // Raw hex belongs in globals.css only (see docs/DESIGN.md).
      'no-restricted-syntax': [
        'error',
        {
          selector: 'Literal[value=/^#(?:[0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/]',
          message: 'No raw hex colors in components. Use a semantic token from globals.css.',
        },
      ],

      eqeqeq: ['error', 'always', { null: 'ignore' }],
      'no-console': ['error', { allow: ['warn', 'error'] }],
    },
  },

  // Config files and scripts run in Node and may log freely.
  {
    files: ['*.config.{ts,mjs,js}', 'scripts/**/*.{ts,mjs,js}'],
    rules: {
      'no-console': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
    },
  },

  // Tests may reach for looser typing when constructing fixtures.
  {
    files: ['**/*.test.{ts,tsx}', 'e2e/**/*.ts', 'vitest.setup.ts'],
    rules: {
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-unsafe-member-access': 'off',
      'no-console': 'off',
    },
  },
)
